document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelectorAll(".tab-btn"),t=document.querySelectorAll(".tab-panel");e.forEach(a=>{a.addEventListener("click",()=>{e.forEach(e=>e.classList.remove("active")),t.forEach(e=>e.classList.remove("active")),a.classList.add("active"),document.getElementById(`tab-${a.dataset.tab}`)?.classList.add("active")})}),document.querySelector(".avatar-edit-btn")?.addEventListener("click",()=>{window.location.href="settings.html"})});